using System;using System.IO;using System.Linq;using System.Text.Json;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class UgoApply{const string Work=@"C:\Users\user\Desktop\02_Справочники_CAD_Revit\odnolineyka\_Разработка\ugo";
static ObjectId Paper(Database db){using(var tr=db.TransactionManager.StartTransaction()){var ld=(DBDictionary)tr.GetObject(db.LayoutDictionaryId,OpenMode.ForRead);return ((Layout)tr.GetObject(ld.GetAt("УГО"),OpenMode.ForRead)).BlockTableRecordId;}}
[CommandMethod("CODEXUGOAPPLYUPDATED",CommandFlags.Session)]public void Run(){try{var target=JsonDocument.Parse(File.ReadAllText(Path.Combine(Work,"added.json"))).RootElement.GetProperty("File").GetString();var doc=AcApp.DocumentManager.Cast<Autodesk.AutoCAD.ApplicationServices.Document>().Single(d=>string.Equals(d.Name,target,StringComparison.OrdinalIgnoreCase));using(var locked=doc.LockDocument()){var db=doc.Database;var paperId=Paper(db);var audit=JsonDocument.Parse(File.ReadAllText(Path.Combine(Work,"hbk_audit.json"))).RootElement.EnumerateArray().Single(d=>d.GetProperty("File").GetString().Equals(target,StringComparison.OrdinalIgnoreCase));var original=audit.GetProperty("Papers").EnumerateArray().Single(p=>p.GetProperty("Layout").GetString()=="УГО").GetProperty("Objects").EnumerateArray().Where(o=>o.TryGetProperty("Handle",out var h)&&h.GetString()!="2C3A4").Select(o=>o.GetProperty("Handle").GetString()).ToHashSet();if(original.Count!=19)throw new System.Exception("Expected original 19 legend objects");ObjectId[] erase;using(var tr=db.TransactionManager.StartTransaction()){var paper=(BlockTableRecord)tr.GetObject(paperId,OpenMode.ForRead);erase=paper.Cast<ObjectId>().Where(id=>original.Contains(id.Handle.ToString())).ToArray();if(erase.Length!=19)throw new System.Exception("Original legend objects changed");var table=erase.Select(id=>tr.GetObject(id,OpenMode.ForRead)).OfType<Table>().Single();if(table.Rows.Count!=19&&table.Rows.Count!=18)throw new System.Exception("Existing legend table changed");}
var backup=Path.Combine(Work,"УГО_до_актуализации_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".dwg");using(var copy=db.Wblock())copy.SaveAs(backup,DwgVersion.Current);
using(var src=new Database(false,true)){src.ReadDwgFile(Path.Combine(Work,"УГО_ХБК_актуализированный.dwg"),FileOpenMode.OpenForReadAndAllShare,true,null);src.CloseInput(true);var sp=Paper(src);ObjectId[] import;using(var tr=src.TransactionManager.StartTransaction()){var b=(BlockTableRecord)tr.GetObject(sp,OpenMode.ForRead);import=b.Cast<ObjectId>().Where(id=>id.Handle.ToString()!="2C3A4"&&tr.GetObject(id,OpenMode.ForRead) is not Viewport).ToArray();if(import.Length!=40||import.Select(id=>tr.GetObject(id,OpenMode.ForRead)).OfType<Table>().Single().Rows.Count!=41)throw new System.Exception("Draft count differs");}
var map=new IdMapping();src.WblockCloneObjects(new ObjectIdCollection(import),paperId,map,DuplicateRecordCloning.MangleName,false);using(var tr=db.TransactionManager.StartTransaction()){foreach(var id in erase)((Entity)tr.GetObject(id,OpenMode.ForWrite)).Erase();var paper=(BlockTableRecord)tr.GetObject(paperId,OpenMode.ForRead);var tab=import.Select(id=>tr.GetObject(map[id].Value,OpenMode.ForRead)).OfType<Table>().Single();var bounds=tab.GeometricExtents;if(bounds.MinPoint.Y<90)throw new System.Exception("Table overlaps stamp");var frame=(BlockReference)tr.GetObject(db.GetObjectId(false,new Handle(0x2C3A4),0),OpenMode.ForRead);var fields=frame.AttributeCollection.Cast<ObjectId>().Select(id=>(AttributeReference)tr.GetObject(id,OpenMode.ForRead)).Select(a=>new{a.Tag,Value=a.TextString,Field=a.HasFields?((Field)tr.GetObject(a.GetField(),OpenMode.ForRead)).GetFieldCode(FieldCodeFlags.FieldCode|FieldCodeFlags.AddMarkers):""}).ToArray();File.WriteAllText(Path.Combine(Work,"update_applied.json"),JsonSerializer.Serialize(new{File=target,Backup=backup,Rows=39,HeatPreserved=true,Bottom=bounds.MinPoint.Y,Fields=fields},new JsonSerializerOptions{WriteIndented=true}));tr.Commit();}}doc.Editor.Regen();}
}catch(System.Exception e){File.WriteAllText(Path.Combine(Work,"apply_update_error.txt"),e.ToString());}}
}
